// Des: Cloud SQL interface, dialects, safe literals, upserts, network client
// Flo: escape text per dialect > build upsert per dialect > Net client sends statements through the vendor adapter > errors are typed
// I/O: statements as text (sync, purge) > rows written in the cloud DB (Turso, Neon, TiDB)
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const cfgz = @import("cf-conf-load.zig"); const turs = @import("sy-clou-turs.zig"); const neon = @import("sy-clou-neon.zig"); const tidb = @import("sy-clou-tidb.zig");
pub const Dial = enum { sqlt, pgsq, mysq };
pub const Kind = enum { turs, neon, tidb };
pub const Sql = struct { ctx: *anyopaque, dial: Dial, exec: *const fn (ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, stmts: []const []const u8) anyerror!void };
pub const Col = struct { name: []const u8, valu: []const u8 };
pub const DDL = [_][]const u8{ "CREATE TABLE IF NOT EXISTS cl_page(urlh CHAR(64) PRIMARY KEY, urlz TEXT, hexz CHAR(64), code INT, tier INT, vend VARCHAR(8), fetc BIGINT)", "CREATE TABLE IF NOT EXISTS cl_reco(urlh CHAR(64) PRIMARY KEY, hexz CHAR(64), kind VARCHAR(8), body TEXT, timz BIGINT)", "CREATE TABLE IF NOT EXISTS cl_manif(hexz CHAR(64) PRIMARY KEY, pack VARCHAR(200), offs BIGINT, lenz BIGINT)", "CREATE TABLE IF NOT EXISTS cl_purg(packz VARCHAR(200) PRIMARY KEY, timz BIGINT, ents INT)" };
pub fn dialOf(kind: Kind) Dial { return switch (kind) { .turs => .sqlt, .neon => .pgsq, .tidb => .mysq }; }
pub fn lit(aren: std.mem.Allocator, dial: Dial, text: []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; try outp.append(aren, '\''); for (text) |byte| { if (byte == 0) return error.BadText; if (byte == '\'') { try outp.appendSlice(aren, "''"); } else if (byte == '\\' and dial == .mysq) { try outp.appendSlice(aren, "\\\\"); } else { try outp.append(aren, byte); } } try outp.append(aren, '\''); return outp.toOwnedSlice(aren); }
pub fn upsert(aren: std.mem.Allocator, dial: Dial, table: []const u8, key: []const u8, cols: []const Col) ![]u8 { var names: std.ArrayList(u8) = .empty; var vals: std.ArrayList(u8) = .empty; var upds: std.ArrayList(u8) = .empty; for (cols, 0..) |col, ix| { if (ix > 0) { try names.appendSlice(aren, ","); try vals.appendSlice(aren, ","); } try names.appendSlice(aren, col.name); try vals.appendSlice(aren, col.valu); if (std.mem.eql(u8, col.name, key)) continue; if (upds.items.len > 0) try upds.appendSlice(aren, ","); if (dial == .mysq) try upds.print(aren, "{s}=VALUES({s})", .{ col.name, col.name }) else try upds.print(aren, "{s}=excluded.{s}", .{ col.name, col.name }); } if (dial == .mysq) return std.fmt.allocPrint(aren, "INSERT INTO {s}({s}) VALUES({s}) ON DUPLICATE KEY UPDATE {s}", .{ table, names.items, vals.items, upds.items }); return std.fmt.allocPrint(aren, "INSERT INTO {s}({s}) VALUES({s}) ON CONFLICT({s}) DO UPDATE SET {s}", .{ table, names.items, vals.items, key, upds.items }); }
pub const Net = struct { kind: Kind, ep: cfgz.Endp, key: []const u8, send: base.Send, gpaz: std.mem.Allocator,
pub fn sql(self: *Net) Sql { return .{ .ctx = self, .dial = dialOf(self.kind), .exec = execz }; }
fn execz(ctx: *anyopaque, aren: std.mem.Allocator, iozz: std.Io, stmts: []const []const u8) anyerror!void { const self: *Net = @ptrCast(@alignCast(ctx)); if (stmts.len == 0) return; switch (self.kind) { .turs => { const back = try self.send.call(self.send.ctx, self.gpaz, iozz, try turs.reqBuild(aren, self.ep, self.key, stmts)); defer self.gpaz.free(back.body); try turs.rspChek(aren, back); }, .neon => for (stmts) |stm| { const back = try self.send.call(self.send.ctx, self.gpaz, iozz, try neon.reqBuild(aren, self.ep, self.key, stm)); defer self.gpaz.free(back.body); try neon.rspChek(back); }, .tidb => for (stmts) |stm| { const back = try self.send.call(self.send.ctx, self.gpaz, iozz, try tidb.reqBuild(aren, self.ep, self.key, stm)); defer self.gpaz.free(back.body); try tidb.rspChek(back); } } } };
